<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">double size       = pet.getProperty (IDs::size, 1.0);</span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;"> // second argument: default</span></span>
